SELECT d.d_year AS year, ca.ca_state AS state, w.w_warehouse_name AS warehouse_name, SUM(ws.ws_ext_sales_price) AS total_sales, COUNT(*) AS order_count, EXISTS (SELECT 1 FROM warehouse w2 WHERE w2.w_warehouse_name = w.w_warehouse_name AND w2.w_warehouse_sq_ft > 185634) AS has_large_warehouse FROM web_sales ws JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk JOIN customer_address ca ON ws.ws_bill_addr_sk = ca.ca_address_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk WHERE d.d_year = 1935 AND ca.ca_state = 'WI' GROUP BY d.d_year, ca.ca_state, w.w_warehouse_name HAVING SUM(ws.ws_ext_sales_price) > 1434.78
